//! Every lane type and object type the 1.9 schema names bakes as the type
//! the crate names for it, and a shared lane is one traffic changes lanes
//! into.
//!
//! `tests/data/all_types.xodr` is generated by `all_types.py`. Road 1 holds one lane
//! of each lane type, in the order below, and one object of each object type.
//! Road 2 holds driving, shared, driving, sidewalk and shared lanes, and
//! roads 3 and 4 continue it.

use xodr::{load_file_with_provenance, LaneType, ObjectType, Provenance, RoadNetwork};

fn fixture() -> (RoadNetwork, Provenance) {
    load_file_with_provenance("tests/data/all_types.xodr").unwrap()
}

/// The lane types road 1 holds, on lanes 1 to 15 and then -1 to -16.
const LANES: [(&str, LaneType); 31] = [
    ("shoulder", LaneType::Shoulder),
    ("border", LaneType::Border),
    ("driving", LaneType::Driving),
    ("stop", LaneType::Stop),
    ("none", LaneType::None),
    ("restricted", LaneType::Restricted),
    ("parking", LaneType::Parking),
    ("median", LaneType::Median),
    ("biking", LaneType::Biking),
    ("shared", LaneType::Shared),
    ("sidewalk", LaneType::Sidewalk),
    ("curb", LaneType::Curb),
    ("exit", LaneType::Exit),
    ("entry", LaneType::Entry),
    ("onRamp", LaneType::OnRamp),
    ("offRamp", LaneType::OffRamp),
    ("connectingRamp", LaneType::ConnectingRamp),
    ("bidirectional", LaneType::Bidirectional),
    ("special1", LaneType::Special1),
    ("special2", LaneType::Special2),
    ("special3", LaneType::Special3),
    ("roadWorks", LaneType::RoadWorks),
    ("tram", LaneType::Tram),
    ("rail", LaneType::Rail),
    ("bus", LaneType::Bus),
    ("taxi", LaneType::Taxi),
    ("HOV", LaneType::Hov),
    ("mwyEntry", LaneType::Entry),
    ("mwyExit", LaneType::Exit),
    ("walking", LaneType::Sidewalk),
    ("slipLane", LaneType::SlipLane),
];

/// The object types road 1 holds, by `<object id>`. The moving participants
/// of older formats and a vendor's own name are `Unknown`.
const OBJECTS: [(&str, ObjectType); 28] = [
    ("none", ObjectType::None),
    ("obstacle", ObjectType::Obstacle),
    ("car", ObjectType::Unknown),
    ("pole", ObjectType::Pole),
    ("tree", ObjectType::Tree),
    ("vegetation", ObjectType::Vegetation),
    ("barrier", ObjectType::Barrier),
    ("building", ObjectType::Building),
    ("parkingSpace", ObjectType::ParkingSpace),
    ("patch", ObjectType::Patch),
    ("railing", ObjectType::Railing),
    ("trafficIsland", ObjectType::TrafficIsland),
    ("crosswalk", ObjectType::Crosswalk),
    ("streetLamp", ObjectType::StreetLamp),
    ("gantry", ObjectType::Gantry),
    ("soundBarrier", ObjectType::SoundBarrier),
    ("van", ObjectType::Unknown),
    ("bus", ObjectType::Unknown),
    ("trailer", ObjectType::Unknown),
    ("bike", ObjectType::Unknown),
    ("motorbike", ObjectType::Unknown),
    ("tram", ObjectType::Unknown),
    ("train", ObjectType::Unknown),
    ("pedestrian", ObjectType::Unknown),
    ("wind", ObjectType::Unknown),
    ("roadMark", ObjectType::RoadMark),
    ("roadSurface", ObjectType::RoadSurface),
    ("banana", ObjectType::Unknown),
];

fn lane_ids() -> impl Iterator<Item = i32> {
    (1..=15).chain((-16..=-1).rev())
}

fn lane<'a>(net: &'a RoadNetwork, prov: &Provenance, road: &str, od_id: i32) -> &'a xodr::Lane {
    let p = prov
        .lanes
        .iter()
        .find(|p| p.road_id == road && p.od_id == od_id)
        .unwrap_or_else(|| panic!("no lane {od_id} on road {road}"));
    net.lane(p.lane).unwrap()
}

#[test]
fn every_lane_type_the_schema_names_bakes_as_the_type_the_crate_names_for_it() {
    let (net, prov) = fixture();
    for (od_id, (name, want)) in lane_ids().zip(LANES) {
        assert_eq!(lane(&net, &prov, "1", od_id).kind, want, "type {name:?}");
    }
}

#[test]
fn every_object_type_the_schema_names_bakes_as_the_type_the_crate_names_for_it() {
    let (net, prov) = fixture();
    assert_eq!(prov.objects.len(), OBJECTS.len());
    for (k, (name, want)) in OBJECTS.into_iter().enumerate() {
        let baked = prov
            .objects
            .iter()
            .find(|o| o.od_id == format!("o{k}"))
            .unwrap_or_else(|| panic!("no object of type {name:?}"));
        assert_eq!(
            net.object(baked.object).unwrap().kind,
            want,
            "type {name:?}"
        );
    }
}

#[test]
fn a_shared_lane_names_itself_and_carries_traffic() {
    assert_eq!(LaneType::Shared.as_str(), "shared");
    assert!(LaneType::Shared.is_drivable());
    assert_eq!(ObjectType::RoadSurface.as_str(), "road-surface");
}

#[test]
fn traffic_changes_lanes_into_a_shared_lane_and_not_into_one_beside_a_sidewalk() {
    let (net, prov) = fixture();
    let neighbors = |road: &str, od_id: i32| -> Vec<i32> {
        let mut found: Vec<i32> = lane(&net, &prov, road, od_id)
            .neighbors
            .iter()
            .map(|n| prov.lanes.iter().find(|p| p.lane == *n).unwrap().od_id)
            .collect();
        found.sort();
        found
    };
    for road in ["2", "3", "4"] {
        assert_eq!(neighbors(road, -1), [-2], "road {road}");
        assert_eq!(neighbors(road, -2), [-3, -1], "road {road}");
        assert_eq!(neighbors(road, -3), [-2], "road {road}");
        assert_eq!(neighbors(road, -4), Vec::<i32>::new(), "road {road}");
        assert_eq!(neighbors(road, -5), Vec::<i32>::new(), "road {road}");
    }
}

#[test]
fn a_shared_lane_leads_into_the_shared_lane_it_links_to() {
    let (net, prov) = fixture();
    let shared = lane(&net, &prov, "2", -2);
    let next = shared
        .successors
        .iter()
        .map(|id| net.lane(*id).unwrap())
        .collect::<Vec<_>>();
    assert_eq!(next.len(), 1);
    assert_eq!(next[0].kind, LaneType::Shared);
    let from_road_3 = prov.lanes.iter().find(|p| p.lane == next[0].id).unwrap();
    assert_eq!((from_road_3.road_id.as_str(), from_road_3.od_id), ("3", -2));
}
